import {bool, oneOf, rule, when} from 'gdp-wired'

export const meterRule = rule("Meter")
  .inputs({method: oneOf('tick'), enabled: bool})
  .state({n: 0})
  .step(({enabled, n}) => ({n: when(enabled, 1, n)}))
